// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (GET /admin/v1/admins)
	ListAdmins(ctx context.Context, request ListAdminsRequestObject) (ListAdminsResponseObject, error)
	// 新建管理员，返回一次性初始密码
	// (POST /admin/v1/admins)
	CreateAdmin(ctx context.Context, request CreateAdminRequestObject) (CreateAdminResponseObject, error)

	// (PATCH /admin/v1/admins/{adminId})
	UpdateAdmin(ctx context.Context, request UpdateAdminRequestObject) (UpdateAdminResponseObject, error)
	// 重置密码，返回一次性新密码
	// (POST /admin/v1/admins/{adminId}/reset-password)
	ResetAdminPassword(ctx context.Context, request ResetAdminPasswordRequestObject) (ResetAdminPasswordResponseObject, error)
	// 审计日志
	// (GET /admin/v1/audit-log)
	ListAuditLog(ctx context.Context, request ListAuditLogRequestObject) (ListAuditLogResponseObject, error)
	// 邮箱密码登录
	// (POST /admin/v1/auth/login)
	AdminLogin(ctx context.Context, request AdminLoginRequestObject) (AdminLoginResponseObject, error)
	// 内置工具与 MCP 白名单（含已下架）
	// (GET /admin/v1/connectors)
	ListConnectors(ctx context.Context, request ListConnectorsRequestObject) (ListConnectorsResponseObject, error)
	// 上下架、默认开启、排序与展示文案。新增 MCP 服务需要改代码（catalog.yaml）后发布
	// (PATCH /admin/v1/connectors/{connectorId})
	UpdateConnector(ctx context.Context, request UpdateConnectorRequestObject) (UpdateConnectorResponseObject, error)
	// 成本：按天、按模型、按任务类型、最高成本用户
	// (GET /admin/v1/costs)
	GetCosts(ctx context.Context, request GetCostsRequestObject) (GetCostsResponseObject, error)
	// 运营概览（按 Asia/Shanghai 计日）
	// (GET /admin/v1/dashboard)
	GetDashboard(ctx context.Context, request GetDashboardRequestObject) (GetDashboardResponseObject, error)
	// 当前管理员
	// (GET /admin/v1/me)
	GetAdminMe(ctx context.Context, request GetAdminMeRequestObject) (GetAdminMeResponseObject, error)
	// 修改自己的密码
	// (POST /admin/v1/me/password)
	ChangeAdminPassword(ctx context.Context, request ChangeAdminPasswordRequestObject) (ChangeAdminPasswordResponseObject, error)
	// 模型网关路由与单价（读自 ZEUS_MODELGW_CONFIG，只读；修改需改文件并重启）及近 24 小时调用
	// (GET /admin/v1/modelgw)
	GetModelGateway(ctx context.Context, request GetModelGatewayRequestObject) (GetModelGatewayResponseObject, error)
	// 拦截记录
	// (GET /admin/v1/moderation/events)
	ListModerationEvents(ctx context.Context, request ListModerationEventsRequestObject) (ListModerationEventsResponseObject, error)
	// 屏蔽词（与 ZEUS_MODERATION_KEYWORDS_FILE 合并生效，约 1 分钟内同步到各进程）
	// (GET /admin/v1/moderation/terms)
	ListModerationTerms(ctx context.Context, request ListModerationTermsRequestObject) (ListModerationTermsResponseObject, error)

	// (POST /admin/v1/moderation/terms)
	CreateModerationTerm(ctx context.Context, request CreateModerationTermRequestObject) (CreateModerationTermResponseObject, error)

	// (DELETE /admin/v1/moderation/terms/{termId})
	DeleteModerationTerm(ctx context.Context, request DeleteModerationTermRequestObject) (DeleteModerationTermResponseObject, error)
	// 方案与额度（代码内配置，只读）
	// (GET /admin/v1/plans)
	ListPlans(ctx context.Context, request ListPlansRequestObject) (ListPlansResponseObject, error)
	// 查看报告正文（审核用）
	// (GET /admin/v1/reports/{reportId})
	GetReport(ctx context.Context, request GetReportRequestObject) (GetReportResponseObject, error)
	// 公开分享的报告
	// (GET /admin/v1/shares)
	ListShares(ctx context.Context, request ListSharesRequestObject) (ListSharesResponseObject, error)
	// 撤销分享链接
	// (POST /admin/v1/shares/{shareId}/revoke)
	RevokeShare(ctx context.Context, request RevokeShareRequestObject) (RevokeShareResponseObject, error)
	// 全部任务
	// (GET /admin/v1/tasks)
	ListTasks(ctx context.Context, request ListTasksRequestObject) (ListTasksResponseObject, error)
	// 任务详情与模型调用明细
	// (GET /admin/v1/tasks/{taskId})
	GetTask(ctx context.Context, request GetTaskRequestObject) (GetTaskResponseObject, error)
	// 取消运行中的任务
	// (POST /admin/v1/tasks/{taskId}/cancel)
	CancelTask(ctx context.Context, request CancelTaskRequestObject) (CancelTaskResponseObject, error)
	// 模板列表；official 为官方模板，custom 为用户自定义模板（用于审核）
	// (GET /admin/v1/templates)
	ListTemplates(ctx context.Context, request ListTemplatesRequestObject) (ListTemplatesResponseObject, error)
	// 新建官方模板
	// (POST /admin/v1/templates)
	CreateTemplate(ctx context.Context, request CreateTemplateRequestObject) (CreateTemplateResponseObject, error)
	// 删除模板（已订阅的简报保留，但与模板解除关联；官方模板建议改为下架）
	// (DELETE /admin/v1/templates/{templateId})
	DeleteTemplate(ctx context.Context, request DeleteTemplateRequestObject) (DeleteTemplateResponseObject, error)

	// (GET /admin/v1/templates/{templateId})
	GetTemplate(ctx context.Context, request GetTemplateRequestObject) (GetTemplateResponseObject, error)
	// 修改模板。官方模板改过后不再被 `zeusctl seed` 覆盖；字段、栏目或来源变化时版本号加 1
	// (PUT /admin/v1/templates/{templateId})
	UpdateTemplate(ctx context.Context, request UpdateTemplateRequestObject) (UpdateTemplateResponseObject, error)
	// 用户列表
	// (GET /admin/v1/users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// 用户详情（额度、定时简报、近 30 天成本）
	// (GET /admin/v1/users/{userId})
	GetUser(ctx context.Context, request GetUserRequestObject) (GetUserResponseObject, error)
	// 修改会员方案
	// (PATCH /admin/v1/users/{userId})
	UpdateUserPlan(ctx context.Context, request UpdateUserPlanRequestObject) (UpdateUserPlanResponseObject, error)
	// 停用账号（注销登录态，暂停其定时简报）
	// (POST /admin/v1/users/{userId}/disable)
	DisableUser(ctx context.Context, request DisableUserRequestObject) (DisableUserResponseObject, error)
	// 恢复账号（恢复因停用而暂停的定时简报）
	// (POST /admin/v1/users/{userId}/enable)
	EnableUser(ctx context.Context, request EnableUserRequestObject) (EnableUserResponseObject, error)
	// 清除额度覆盖
	// (DELETE /admin/v1/users/{userId}/quota)
	ClearUserQuota(ctx context.Context, request ClearUserQuotaRequestObject) (ClearUserQuotaResponseObject, error)
	// 设置额度覆盖（字段为空表示沿用方案额度）
	// (PUT /admin/v1/users/{userId}/quota)
	SetUserQuota(ctx context.Context, request SetUserQuotaRequestObject) (SetUserQuotaResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListAdmins operation middleware
func (sh *strictHandler) ListAdmins(w http.ResponseWriter, r *http.Request) {
	var request ListAdminsRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListAdmins(ctx, request.(ListAdminsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListAdmins")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListAdminsResponseObject); ok {
		if err := validResponse.VisitListAdminsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

